$:node <<'NODE'
"use strict";
const cp = require("node:child_process");
const specs = [
  {
    path: ".github/workflows/issue-10-runtimeconfig.yml",
    old: "github.event.issue.number == 10 &&\n          ",
    replacement: ""
  },
  {
    path: "workspaces/RuntimeConfig/prepare-runtrigger.js",
    old: "id <= 0 || number !== 10",
    replacement: "id <= 0"
  }
];
function gh(args) {
  const p=cp.spawnSync("gh",["api",...args],{encoding:"utf8",timeout:45000,maxBuffer:10*1024*1024});
  if (p.error||p.status!==0) throw Error(p.error?.message||p.stderr);
  return JSON.parse(p.stdout);
}
for (const item of specs) {
  const api="repos/BestNameYet/Terminals/contents/"+item.path;
  const before=gh([api]);
  const text=Buffer.from(before.content.replace(/\s/g,""),"base64").toString("utf8");
  const count=text.split(item.old).length-1;
  if (count!==1) throw Error("Expected exactly one target condition in "+item.path+"; found "+count);
  const updated=text.replace(item.old,item.replacement);
  const out=gh([api,"--method","PUT","-f","message=Remove Issue 10 number gate from "+item.path,"-f","sha="+before.sha,"-f","content="+Buffer.from(updated,"utf8").toString("base64")]);
  const read=gh([api]);
  const readText=Buffer.from(read.content.replace(/\s/g,""),"base64").toString("utf8");
  if (readText!==updated) throw Error("Remote readback mismatch: "+item.path);
  console.log(JSON.stringify({file:item.path,gateRemoved:true,readbackVerified:true,commit:out.commit?.sha}));
}
NODE
